import{_ as e,c as r,a2 as t,o as i}from"./chunks/framework.BQmytedh.js";const u=JSON.parse('{"title":"几十年治痘经验总结，痘痘常用外用药全指南","description":"","frontmatter":{},"headers":[],"relativePath":"护肤/知乎_瑞颜医生/得此文者得天下.md","filePath":"护肤/知乎_瑞颜医生/得此文者得天下.md","lastUpdated":1733938304000}'),h={name:"护肤/知乎_瑞颜医生/得此文者得天下.md"};function o(n,a,l,p,d,s){return i(),r("div",null,a[0]||(a[0]=[t('<h1 id="几十年治痘经验总结-痘痘常用外用药全指南" tabindex="-1">几十年治痘经验总结，痘痘常用外用药全指南 <a class="header-anchor" href="#几十年治痘经验总结-痘痘常用外用药全指南" aria-label="Permalink to &quot;几十年治痘经验总结，痘痘常用外用药全指南&quot;">​</a></h1><p><a href="https://zhuanlan.zhihu.com/p/374837223" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/374837223</a></p><p>今天的文章中，我把痘痘常用的外用药膏做了一个集合整理，涉及其<strong>原理、用法、注意事项</strong>等。</p><p>都是这些年的治痘经验总结，所以有很多独家的细节，都是干货，建议边喝水边看，也可以先收藏。</p><h2 id="阿达帕林" tabindex="-1">阿达帕林 <a class="header-anchor" href="#阿达帕林" aria-label="Permalink to &quot;阿达帕林&quot;">​</a></h2><p><a href="https://www.zhihu.com/question/64456413/answer/1768882365" target="_blank" rel="noreferrer">深度讲解</a></p><p>阿达帕林属于维A酸类外用药，属于外用祛痘药膏中的百搭型选手，啥样的痘痘都可以用，无论黑头闭口，红肿痘痘，痘印痘坑，阿达帕林都可以搭进去。</p><p>如果你只是闭口黑头这种不严重的痘痘，你甚至可以只使用阿达帕林。</p><p>托尔斯泰说过，当你听说阿达帕林的时候，你的痘已经好了50%，当你学会正确使用阿达帕林的时候，你的痘就好了90%。</p><h3 id="阿达帕林要注意的地方很多" tabindex="-1">阿达帕林要注意的地方很多 <a class="header-anchor" href="#阿达帕林要注意的地方很多" aria-label="Permalink to &quot;阿达帕林要注意的地方很多&quot;">​</a></h3><ol><li><p>阿达帕林有刺激性，敏感皮肤的患者不要用，同时建议在涂抹保湿修复霜之后使用。如果你不知道你是不是敏感皮肤，你就先试试，只要感觉不刺激就可以用。</p></li><li><p>也是因为刺激性，阿达帕林需要点涂或局部涂抹。</p></li><li><p>备孕期/怀孕期/哺乳期女性不建议使用，维A酸有致畸性。</p></li><li><p>阿达帕林<strong>不能</strong>和<a href="#过氧苯甲酰凝胶班赛">过氧苯甲酰凝胶</a>，也就是班赛，同时使用，刺激性太强了，强调一下同时使用是指涂完一种药立刻涂另一种药。如果是早上用班赛，晚上用阿达帕林一点问题都没有啊。</p></li><li><p>使用期间需要严格防晒。</p></li><li><p>用手涂，不要用棉签涂，这个的具体原理我们真没去做过实验验证，但是根据经验，棉签涂药的患者，效果普遍不如手涂药的患者。</p></li></ol><h3 id="建立耐受-1" tabindex="-1">建立耐受[^1] <a class="header-anchor" href="#建立耐受-1" aria-label="Permalink to &quot;建立耐受[^1]&quot;">​</a></h3><p>啥叫建立耐受？就是让你先适应一下刺激，刺激刺激着就习惯了，建立耐受请看如下步骤：</p><ol><li>第一天，涂在脸上停留5-10分钟后立刻清水洗掉；</li><li>第二天，停留时间可以放宽到15-20分钟；</li><li>以此类推，当停留超过1-2小时无任何不适时，可以不清洗，直接过夜；</li><li>前期如果感觉有轻微不适，可以暂且隐忍，如果有严重不适，需要立刻清洗停药；</li></ol><h2 id="维a酸乳膏" tabindex="-1">维A酸乳膏 <a class="header-anchor" href="#维a酸乳膏" aria-label="Permalink to &quot;维A酸乳膏&quot;">​</a></h2><p>维A酸可以溶解粉刺，抑制皮脂分泌，也有一定的抗炎作用，<strong>在粉刺阶段，单独使用维A酸乳膏就能有不错的治疗效果。</strong></p><p>它跟阿达帕林凝胶同属于维A酸类药物，它是第一代，阿达帕林是第三代。</p><p>他俩的关系恰如百事可乐和可口可乐，上校鸡块和麦乐鸡块，老北京鸡肉卷和墨西哥鸡肉卷，大同小异。</p><p>维A酸乳膏和阿达帕林要注意的也差不多，同样的有刺激性，同样的点涂，同样的敏感皮肤和孕期女性禁用，同样的不能和班赛一起用，同样的需要严格防晒。</p><p><strong>不同的是，维A酸乳膏刺激性会更大一些，所以优先建议使用阿达帕林；</strong></p><p>维A酸乳膏是乳霜，更厚重，建议秋冬季节和干皮患者使用，阿达帕林是凝胶，更清爽，建议夏天和油皮患者使用。</p><h3 id="kind-1" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-1" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-1}&quot;">​</a></h3><p>闭口粉刺、黑头粉刺、红肿痘痘、痘印、痘坑</p><h3 id="when-1" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-1" aria-label="Permalink to &quot;什么时候涂药 {#when-1}&quot;">​</a></h3><p>维A酸有一定光敏性，所以应该晚上涂</p><h3 id="how-1" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-1" aria-label="Permalink to &quot;怎么涂药 {#how-1}&quot;">​</a></h3><ol><li><p>点涂或局部</p></li><li><p>需要建立耐受，前几次可以先涂保湿修复霜，再局部点涂，涂抹后可以用手按摩一会</p></li></ol><h3 id="irritating-1" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-1" aria-label="Permalink to &quot;是否有刺激性 {#irritating-1}&quot;">​</a></h3><p>药物浓度不同，刺激性不同，整体来说刺激性较强，敏感皮肤禁用</p><h3 id="people-1" tabindex="-1">人群选择 <a class="header-anchor" href="#people-1" aria-label="Permalink to &quot;人群选择 {#people-1}&quot;">​</a></h3><ol><li><p>备孕期/怀孕期/哺乳期妇女不能使用</p></li><li><p>敏感皮肤人群不能使用</p></li></ol><h3 id="attention-1" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-1" aria-label="Permalink to &quot;其他注意事项 {#attention-1}&quot;">​</a></h3><ol><li><p>不能与过氧苯甲酰凝胶（班赛）同时使用，可以早上涂班赛，晚上涂维A酸乳膏</p></li><li><p>需要严格防晒</p></li></ol><h2 id="克林霉素凝胶" tabindex="-1">克林霉素凝胶 <a class="header-anchor" href="#克林霉素凝胶" aria-label="Permalink to &quot;克林霉素凝胶&quot;">​</a></h2><p>大红痘痘的特征是细菌导致的炎症，所以消炎杀菌很重要。</p><p><strong>克林霉素磷酸酯凝胶</strong>是一种抗生素，对使用的时间段，涂抹方式，适宜人群等没啥特殊要求。</p><p>唯一注意的是作为一名抗生素，是会存在耐药性的，所以一般使用的时候我们会和过氧苯甲酰凝胶或阿达帕林联合交替使用。</p><p><strong>比如晚上涂阿达帕林，星期一三五七早上涂克林霉素凝胶，星期二四六八早上涂班赛。</strong></p><p>在痘痘炎症消退，也就是不再红肿过后，就可以停药了。属于抗生素，可以干掉痤疮丙酸杆菌，消除炎症。</p><h3 id="kind-2" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-2" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-2}&quot;">​</a></h3><p>红肿痘痘</p><h3 id="when-2" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-2" aria-label="Permalink to &quot;什么时候涂药 {#when-2}&quot;">​</a></h3><p>早晚均可</p><h3 id="how-2" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-2" aria-label="Permalink to &quot;怎么涂药 {#how-2}&quot;">​</a></h3><p>点涂和大面积涂抹均可</p><h3 id="irritating-2" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-2" aria-label="Permalink to &quot;是否有刺激性 {#irritating-2}&quot;">​</a></h3><p>一般无刺激性</p><h3 id="people-2" tabindex="-1">人群选择 <a class="header-anchor" href="#people-2" aria-label="Permalink to &quot;人群选择 {#people-2}&quot;">​</a></h3><p>1.敏感皮肤人群可以使用</p><p>2.备孕期/怀孕期/哺乳期可以使用</p><h3 id="attention-2" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-2" aria-label="Permalink to &quot;其他注意事项 {#attention-2}&quot;">​</a></h3><p>1.不建议单独使用，可与过氧苯甲酰或阿达帕林联合使用</p><p>2.痘痘炎症消退后（不再红肿），即可停药</p><p>3.一般早上涂克林霉素，晚上涂班赛或者阿达帕林</p><h2 id="克林霉素甲硝唑擦剂" tabindex="-1">克林霉素甲硝唑擦剂 <a class="header-anchor" href="#克林霉素甲硝唑擦剂" aria-label="Permalink to &quot;克林霉素甲硝唑擦剂&quot;">​</a></h2><p><strong>克林霉素甲硝唑搽剂</strong>跟刚刚的<strong>克林霉素磷酸酯凝胶</strong>的区别就在于：<strong>这里面加了甲硝唑，也加了酒精等。</strong></p><p>这就造成了它更容易吸收，<strong>但同时也有一定的刺激性</strong>，毕竟酒精还是很刺激的。</p><p><strong>所以皮肤敏感的患者慎用。</strong></p><p>但如果能耐受，红肿痘痘消的还真是挺快的。</p><p>值得注意的是，因为添加了甲硝唑，在说明书中有标明，孕期女性慎用，所以有患者处于备孕/怀孕/哺乳期，请咨询主治医生。</p><p>其他注意事项一样，不要单独使用，多联合其他药物使用，对抗耐药性。</p><h3 id="适合什么样的痘痘使用" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#适合什么样的痘痘使用" aria-label="Permalink to &quot;适合什么样的痘痘使用&quot;">​</a></h3><p>红肿痘痘</p><h3 id="什么时候涂药" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#什么时候涂药" aria-label="Permalink to &quot;什么时候涂药&quot;">​</a></h3><p>早晚均可</p><h3 id="怎么涂药" tabindex="-1">怎么涂药 <a class="header-anchor" href="#怎么涂药" aria-label="Permalink to &quot;怎么涂药&quot;">​</a></h3><p>点涂或局部</p><h3 id="是否有刺激性" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#是否有刺激性" aria-label="Permalink to &quot;是否有刺激性&quot;">​</a></h3><p>有刺激性</p><h3 id="人群选择" tabindex="-1">人群选择 <a class="header-anchor" href="#人群选择" aria-label="Permalink to &quot;人群选择&quot;">​</a></h3><p>1.敏感皮肤人群不建议使用</p><p>2.备孕期/怀孕期/哺乳期请根据医生指导是否使用</p><h3 id="其他注意事项" tabindex="-1">其他注意事项 <a class="header-anchor" href="#其他注意事项" aria-label="Permalink to &quot;其他注意事项&quot;">​</a></h3><p>1.不建议单独使用，可与过氧苯甲酰或阿达帕林联合使用</p><p>2.痘痘炎症消退后（不再红肿），即可停药</p><p>3.一般早上涂克林霉素，晚上涂班赛或者阿达帕林</p><h2 id="夫西地酸乳膏" tabindex="-1">夫西地酸乳膏 <a class="header-anchor" href="#夫西地酸乳膏" aria-label="Permalink to &quot;夫西地酸乳膏&quot;">​</a></h2><p>跟克林霉素一样，夫西地酸也属于抗生素。</p><p>需要注意的第一点仍然是耐药性，同样的，早上交替使用夫西地酸和其他抗菌药物，晚上使用阿达帕林或维A酸乳膏。</p><p>第二点，夫西地酸乳膏说明书中有提到孕期女性慎用，处于备孕/怀孕/哺乳期的患者记得咨询主治医生哦。</p><h3 id="kind-3" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-3" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-3}&quot;">​</a></h3><p>红肿痘痘</p><h3 id="when-3" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-3" aria-label="Permalink to &quot;什么时候涂药 {#when-3}&quot;">​</a></h3><p>早晚均可</p><h3 id="how-3" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-3" aria-label="Permalink to &quot;怎么涂药 {#how-3}&quot;">​</a></h3><p>点涂和大面积涂抹均可</p><h3 id="irritating-3" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-3" aria-label="Permalink to &quot;是否有刺激性 {#irritating-3}&quot;">​</a></h3><p>一般无刺激性，偶尔会有轻微刺激感</p><h3 id="people-3" tabindex="-1">人群选择 <a class="header-anchor" href="#people-3" aria-label="Permalink to &quot;人群选择 {#people-3}&quot;">​</a></h3><p>1.敏感皮肤人群可以使用</p><p>2.备孕期/怀孕期/哺乳期慎用</p><h3 id="attention-3" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-3" aria-label="Permalink to &quot;其他注意事项 {#attention-3}&quot;">​</a></h3><p>1.不建议单独使用，可与过氧苯甲酰或阿达帕林联合使用</p><p>2.痘痘炎症消退后（不再红肿），即可停药</p><p>3.一般早上涂夫西地酸乳膏，晚上涂班赛或者阿达帕林</p><h2 id="甲硝唑凝胶" tabindex="-1">甲硝唑凝胶 <a class="header-anchor" href="#甲硝唑凝胶" aria-label="Permalink to &quot;甲硝唑凝胶&quot;">​</a></h2><p>甲硝唑凝胶这个药最近很火。</p><p>但甲硝唑不治闭口也不治黑头，甲硝唑属于抗生素，对于大红痘痘这样的炎性丘疹是有用的。</p><p>真要治疗闭口黑头，请看看维A酸类药物，比如开头的的阿达帕林和维A酸乳膏。</p><p>同样的，作为抗生素，就是一个耐药性问题，通过药物联合使用和交替使用可以应对。</p><p>还有，<strong>甲硝唑凝胶的说明书中有标明孕期女性慎用，所以有患者处于备孕/怀孕/哺乳期，请咨询主治医生。</strong></p><h3 id="kind-4" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-4" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-4}&quot;">​</a></h3><p>红肿痘痘</p><h3 id="when-4" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-4" aria-label="Permalink to &quot;什么时候涂药 {#when-4}&quot;">​</a></h3><p>早晚均可</p><h3 id="how-4" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-4" aria-label="Permalink to &quot;怎么涂药 {#how-4}&quot;">​</a></h3><p>点涂和大面积涂抹均可</p><h3 id="irritating-4" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-4" aria-label="Permalink to &quot;是否有刺激性 {#irritating-4}&quot;">​</a></h3><p>一般无刺激性</p><h3 id="people-4" tabindex="-1">人群选择 <a class="header-anchor" href="#people-4" aria-label="Permalink to &quot;人群选择 {#people-4}&quot;">​</a></h3><p>1.敏感皮肤人群可以使用</p><p>2.备孕期/怀孕期/哺乳期慎用</p><h3 id="attention-4" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-4" aria-label="Permalink to &quot;其他注意事项 {#attention-4}&quot;">​</a></h3><p>1.不建议单独使用，可与过氧苯甲酰或阿达帕林联合使用</p><p>2.痘痘炎症消退后（不再红肿），即可停药</p><p>3.一般早上涂甲硝唑凝胶，晚上涂班赛或者阿达帕林</p><h2 id="过氧苯甲酰凝胶-班赛" tabindex="-1">过氧苯甲酰凝胶（班赛） <a class="header-anchor" href="#过氧苯甲酰凝胶-班赛" aria-label="Permalink to &quot;过氧苯甲酰凝胶（班赛）&quot;">​</a></h2><p>终于轮到一直提到的过氧苯甲酰凝胶了。</p><p>发明了维A酸乳膏的克里格曼教授，也是过氧苯甲酰凝胶的发明者之一。</p><p>这个药也是痘痘治疗中很重要的药物，它能够通过氧化作用杀死细菌，控制炎症，还能够控油抗角化。</p><p>关键点来了，过氧苯甲酰这个药杀菌是靠氧化作用，跟抗生素不一样，所以，<strong>它不会有耐药性</strong>。</p><p>但值得注意的是，<strong>过氧苯甲酰凝胶有较强的刺激性，只能点涂和局部使用，同时敏感皮肤人群不建议使用。</strong></p><p>根据最新说明书，过氧苯甲酰怀孕期人群不建议使用。</p><p>一般在痘痘的维持治疗阶段，就是早上过氧苯甲酰凝胶，晚上阿达帕林凝胶。</p><h3 id="kind-5" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-5" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-5}&quot;">​</a></h3><p>粉刺、红肿痘痘、痘印、痘坑</p><h3 id="when-5" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-5" aria-label="Permalink to &quot;什么时候涂药 {#when-5}&quot;">​</a></h3><p>早晚均可</p><h3 id="how-5" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-5" aria-label="Permalink to &quot;怎么涂药 {#how-5}&quot;">​</a></h3><p>1.点涂或局部</p><p>2.需要建立耐受</p><h3 id="irritating-5" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-5" aria-label="Permalink to &quot;是否有刺激性 {#irritating-5}&quot;">​</a></h3><p>刺激性较强，敏感皮肤慎用</p><h3 id="people-5" tabindex="-1">人群选择 <a class="header-anchor" href="#people-5" aria-label="Permalink to &quot;人群选择 {#people-5}&quot;">​</a></h3><p>1.敏感皮肤人群不能使用</p><p>2.怀孕期女性不能使用</p><h3 id="attention-5" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-5" aria-label="Permalink to &quot;其他注意事项 {#attention-5}&quot;">​</a></h3><p>1.不能与维A酸同时使用，可以早上涂班赛，晚上涂维A酸；</p><p>2.可用作维持治疗，不会产生耐药性，这是它最大的优势</p><h2 id="积雪苷霜软膏" tabindex="-1">积雪苷霜软膏 <a class="header-anchor" href="#积雪苷霜软膏" aria-label="Permalink to &quot;积雪苷霜软膏&quot;">​</a></h2><p>积雪苷酸软膏这个药在烧伤科比较常见，可以促进创面愈合和抑制瘢痕的增生。</p><p>对于已有的痘坑痘疤，这个药更多是起到软化效果，如果想要治疗痘坑，建议采用综合治疗方案。</p><p>积雪苷酸软膏比较温和，一般来说绝大多数人群都能正常使用。</p><p>主要软化疤痕，对痘坑痘疤痘印都有一定作用。</p><h3 id="kind-6" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-6" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-6}&quot;">​</a></h3><p>痘坑</p><h3 id="when-6" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-6" aria-label="Permalink to &quot;什么时候涂药 {#when-6}&quot;">​</a></h3><p>建议早上涂积雪苷乳膏，晚上涂阿达帕林或者维a酸乳膏</p><h3 id="how-6" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-6" aria-label="Permalink to &quot;怎么涂药 {#how-6}&quot;">​</a></h3><p>点涂和大面积涂抹均可</p><h3 id="irritating-6" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-6" aria-label="Permalink to &quot;是否有刺激性 {#irritating-6}&quot;">​</a></h3><p>一般无刺激性</p><h3 id="people-6" tabindex="-1">人群选择 <a class="header-anchor" href="#people-6" aria-label="Permalink to &quot;人群选择 {#people-6}&quot;">​</a></h3><p>1.敏感皮肤人群可以使用</p><p>2.备孕期/怀孕期/哺乳期可以使用</p><h2 id="喜辽妥-多磺酸粘多糖乳膏" tabindex="-1">喜辽妥（多磺酸粘多糖乳膏） <a class="header-anchor" href="#喜辽妥-多磺酸粘多糖乳膏" aria-label="Permalink to &quot;喜辽妥（多磺酸粘多糖乳膏）&quot;">​</a></h2><p>喜辽妥，也叫多磺酸粘多糖乳膏。</p><p>喜辽妥与积雪苷酸软膏类似，可以起到软化瘢痕的效果，真想治痘坑还得采取综合治疗方案。</p><p>值得注意的是，喜辽妥不能用于开放性伤口和破损的皮肤上。</p><p>主要软化疤痕，对痘坑痘疤痘印都有一定作用。</p><h3 id="kind-7" tabindex="-1">适合什么样的痘痘使用 <a class="header-anchor" href="#kind-7" aria-label="Permalink to &quot;适合什么样的痘痘使用 {#kind-7}&quot;">​</a></h3><p>痘印、痘坑、痘疤</p><h3 id="when-7" tabindex="-1">什么时候涂药 <a class="header-anchor" href="#when-7" aria-label="Permalink to &quot;什么时候涂药 {#when-7}&quot;">​</a></h3><p>建议早上涂喜辽妥，晚上涂阿达帕林或者维a酸乳膏</p><h3 id="how-7" tabindex="-1">怎么涂药 <a class="header-anchor" href="#how-7" aria-label="Permalink to &quot;怎么涂药 {#how-7}&quot;">​</a></h3><p>点涂和大面积涂抹均可</p><h3 id="irritating-7" tabindex="-1">是否有刺激性 <a class="header-anchor" href="#irritating-7" aria-label="Permalink to &quot;是否有刺激性 {#irritating-7}&quot;">​</a></h3><p>一般无刺激性</p><h3 id="people-7" tabindex="-1">人群选择 <a class="header-anchor" href="#people-7" aria-label="Permalink to &quot;人群选择 {#people-7}&quot;">​</a></h3><p>1.敏感皮肤人群可以使用</p><p>2.备孕期/怀孕期/哺乳期可以使用</p><h3 id="attention-7" tabindex="-1">其他注意事项 <a class="header-anchor" href="#attention-7" aria-label="Permalink to &quot;其他注意事项 {#attention-7}&quot;">​</a></h3><p>开放性伤口和破损的皮肤禁用</p><h2 id="技术总结" tabindex="-1">技术总结 <a class="header-anchor" href="#技术总结" aria-label="Permalink to &quot;技术总结&quot;">​</a></h2><p>最后我们再来分类总结一下：</p><h3 id="按痘痘类型分类" tabindex="-1">按痘痘类型分类 <a class="header-anchor" href="#按痘痘类型分类" aria-label="Permalink to &quot;按痘痘类型分类&quot;">​</a></h3><h4 id="闭口粉刺黑头" tabindex="-1">闭口粉刺黑头 <a class="header-anchor" href="#闭口粉刺黑头" aria-label="Permalink to &quot;闭口粉刺黑头&quot;">​</a></h4><p>阿达帕林凝胶、维A酸乳膏、过氧苯甲酰凝胶（班赛）</p><h4 id="红肿痘痘" tabindex="-1">红肿痘痘 <a class="header-anchor" href="#红肿痘痘" aria-label="Permalink to &quot;红肿痘痘&quot;">​</a></h4><p>阿达帕林、克林霉素凝胶、夫西地酸乳膏、甲硝唑凝胶、过氧苯甲酰凝胶（班赛）、克林霉素甲硝唑擦剂</p><h4 id="痘坑痘印" tabindex="-1">痘坑痘印 <a class="header-anchor" href="#痘坑痘印" aria-label="Permalink to &quot;痘坑痘印&quot;">​</a></h4><p>过氧苯甲酰凝胶（班赛）、阿达帕林、喜辽妥（多磺酸粘多糖乳膏）、积雪苷霜软膏</p><p>（不同类型痘痘的照片可能会因为不适，我放在评论区~）</p><h3 id="禁用分类" tabindex="-1">禁用分类 <a class="header-anchor" href="#禁用分类" aria-label="Permalink to &quot;禁用分类&quot;">​</a></h3><h4 id="有刺激性-敏感皮肤禁用" tabindex="-1">有刺激性，敏感皮肤禁用 <a class="header-anchor" href="#有刺激性-敏感皮肤禁用" aria-label="Permalink to &quot;有刺激性，敏感皮肤禁用&quot;">​</a></h4><p>维A酸乳膏、阿达帕林凝胶、过氧苯甲酰凝胶（班赛）</p><h4 id="孕妇禁用-慎用" tabindex="-1">孕妇禁用/慎用 <a class="header-anchor" href="#孕妇禁用-慎用" aria-label="Permalink to &quot;孕妇禁用/慎用&quot;">​</a></h4><p>维A酸乳膏、阿达帕林凝胶、夫西地酸乳膏、克林霉素甲硝唑搽剂、甲硝唑凝胶</p><p>以上就是我这些年对于祛痘外用药物的临床经验总结了，希望对大家有所帮助。</p><p><strong>其实，我们还是鼓励痘痘患者们来医院或者网上诊室看医生，极其不建议个人购买药物自己使用的。</strong></p><p>毕竟化妆品都能用出刺激性皮炎和敏感皮肤，更何况是药呢。</p><p>我们发现实在太多人在网上查攻略自己给自己治痘了，这种情况下我们高喊着大家不要自己用也不现实，而且，也没多少人看得到我们。</p><p>所以，我们干脆出一期类似说明书的经验总结，希望能帮到一些人。</p><p>我们会持续给大家带来更多与痘痘相关，与皮肤相关的科普和案例，祝大家肤如凝脂，吹弹可破。</p><p>[^1]: <a href="https://www.zhihu.com/question/64456413/answer/1768882365" target="_blank" rel="noreferrer">瑞颜医生​​(第四军医大学 皮肤与性病学博士): 维a酸乳膏可以去痘印吗？</a></p>',195)]))}const b=e(h,[["render",o]]);export{u as __pageData,b as default};
